// ══════════════════════════════════════════════════════════════════════════════
// Aero Piston Engine Digital Twin — Mission Replay Toolbar
// ══════════════════════════════════════════════════════════════════════════════
//
// Plays a stored mission back through the live cockpit widgets.
//
//   POST /api/replay/start              — validates the mission, reports size
//   GET  /api/replay/frames/{mission}   — the stored telemetry rows
//   GET  /api/reports/{mission}/health-timeline — the twin's per-tick scores
//   GET  /api/replay/status             — what the backend thinks is playing
//
// The telemetry rows and the health timeline are joined on sim_time_s and
// pushed into the telemetry context, so every gauge, chart and the 3D twin
// render a past mission exactly as they rendered it live.
//
// Note: the backend's ReplayService can stream frames over the WebSocket, but
// the route does not start it — POST /api/replay/start returns the frame count
// and stops there. Playback therefore runs client-side off the frame endpoint.
// ══════════════════════════════════════════════════════════════════════════════

import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import {
  Pause,
  Play,
  RotateCcw,
  SkipBack,
  SkipForward,
  Clock,
  X,
} from 'lucide-react';
import clsx from 'clsx';

import api from '../../services/api';
import { useTelemetry, type TelemetryFrame } from '../../context/TelemetryContext';
import { describeApiError, useApiResource } from '../../hooks/useApiResource';
import { buildReplayFrames, fmtClock, type ReplayHealthRow, type ReplayTelemetryRow } from '../../lib/adapters';
import { useToast } from '../ui/Toast';

interface MissionReplayToolbarProps {
  className?: string;
  /** Mission to preselect (e.g. the one picked in the mission browser). */
  missionId?: string | null;
  onFrameSelect?: (frameIndex: number) => void;
}

interface TimelineMarker {
  at: number; // 0-100 %
  type: 'anomaly' | 'fault' | 'rtb';
  label: string;
  severity: 'warning' | 'critical';
}

const PLAYBACK_SPEEDS = [1, 2, 5] as const;
const MAX_REPLAY_FRAMES = 5000;

export default function MissionReplayToolbar({
  className,
  missionId,
  onFrameSelect,
}: MissionReplayToolbarProps) {
  const {
    replayData,
    replayIndex,
    replaySpeed,
    replayPlaying,
    isReplayMode,
    startReplay,
    stopReplay,
    setReplaySpeed,
    seekReplay,
    setReplayPlaying,
  } = useTelemetry();
  const { addToast } = useToast();

  const missions = useApiResource(() => api.missions.list(50), { intervalMs: 30_000 });
  const backendReplay = useApiResource(() => api.replay.status(), { intervalMs: 10_000 });

  const [selected, setSelected] = useState<string | null>(missionId ?? null);
  const [loading, setLoading] = useState(false);
  const [markers, setMarkers] = useState<TimelineMarker[]>([]);
  const [scrub, setScrub] = useState<number | null>(null);
  const commitTimer = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(() => () => {
    if (commitTimer.current) clearTimeout(commitTimer.current);
  }, []);

  /*  Anything that is not still running has stored frames to replay.  The
      frame count is the primary signal, but older rows predate the backend
      tracking it, so a finished mission is offered either way.  */
  const playable = useMemo(
    () =>
      (missions.data?.missions ?? []).filter(
        (m) => (m.frame_count ?? 0) > 0 || m.status !== 'RUNNING'
      ),
    [missions.data]
  );

  useEffect(() => {
    if (!selected && playable.length > 0) setSelected(playable[0].mission_id);
  }, [playable, selected]);

  // ── load a mission ────────────────────────────────────────────────────────

  const load = useCallback(async () => {
    if (!selected) {
      addToast('Pick a mission to replay first', 'info');
      return;
    }

    setLoading(true);
    try {
      // 404s for an unknown mission, and tells us how many frames it holds.
      const session = await api.replay.start({ mission_id: selected, speed: replaySpeed });

      const [frames, timeline] = await Promise.all([
        api.replay.frames(selected, MAX_REPLAY_FRAMES),
        api.reports
          .healthTimeline(selected)
          .catch(() => ({ mission_id: selected, count: 0, data: [] })),
      ]);

      const rows = (frames.data ?? []) as unknown as ReplayTelemetryRow[];
      if (rows.length === 0) {
        addToast('That mission has no stored telemetry yet', 'warning');
        return;
      }

      const built = buildReplayFrames(rows, (timeline.data ?? []) as unknown as ReplayHealthRow[]);
      // The adapter emits the same flattened frame the live socket produces
      // (cylinder arrays rather than tuples), which is exactly what the
      // cockpit widgets consume.
      startReplay(built as unknown as TelemetryFrame[]);
      setMarkers(buildMarkers(built));
      addToast(
        `Replaying ${built.length} frames of ${session.frame_count ?? rows.length}`,
        'info'
      );
    } catch (err) {
      addToast(`Replay failed — ${describeApiError(err)}`, 'error');
    } finally {
      setLoading(false);
    }
  }, [addToast, replaySpeed, selected, startReplay]);

  // ── controls ──────────────────────────────────────────────────────────────

  const position =
    replayData.length > 0 ? (replayIndex / Math.max(1, replayData.length - 1)) * 100 : 0;
  const shown = scrub ?? position;

  const step = useCallback(
    (fraction: number) => {
      const amount = Math.max(1, Math.floor(replayData.length * fraction));
      seekReplay(Math.min(replayData.length - 1, Math.max(0, replayIndex + amount)));
    },
    [replayData.length, replayIndex, seekReplay]
  );

  const onScrub = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      const value = Number(e.target.value);
      setScrub(value);
      if (commitTimer.current) clearTimeout(commitTimer.current);
      commitTimer.current = setTimeout(() => {
        const index = Math.floor((value / 100) * Math.max(0, replayData.length - 1));
        seekReplay(index);
        onFrameSelect?.(index);
        setScrub(null);
      }, 120);
    },
    [onFrameSelect, replayData.length, seekReplay]
  );

  const frame = replayData[replayIndex];

  return (
    <div className={clsx('hud-panel', className)}>
      <div className="flex items-center justify-between mb-4">
        <div className="flex items-center gap-2">
          <Clock className="w-4 h-4 text-cyber-cyan" />
          <h3 className="text-sm font-medium text-cockpit-muted">Mission Replay</h3>
        </div>
        {isReplayMode && (
          <button
            onClick={() => {
              stopReplay();
              setMarkers([]);
            }}
            className="flex items-center gap-1 px-2 py-1 rounded text-xs bg-cockpit-surface text-cockpit-muted hover:bg-cockpit-border transition-colors"
          >
            <X className="w-3 h-3" /> Exit replay
          </button>
        )}
      </div>

      {/* Mission picker */}
      <div className="flex gap-2 mb-4">
        <select
          value={selected ?? ''}
          onChange={(e) => setSelected(e.target.value || null)}
          className="flex-1 px-2 py-2 rounded-lg bg-cockpit-bg border border-cockpit-border text-xs text-white focus:border-cyber-cyan outline-none"
        >
          {playable.length === 0 && <option value="">No stored missions</option>}
          {playable.map((m) => (
            <option key={m.mission_id} value={m.mission_id}>
              {(m.name || `Mission ${m.mission_id.slice(0, 8)}`)} · {m.frame_count} frames
            </option>
          ))}
        </select>
        <button
          onClick={load}
          disabled={loading || !selected}
          className="px-3 py-2 rounded-lg bg-cyber-cyan/20 text-cyber-cyan border border-cyber-cyan/40 hover:bg-cyber-cyan/30 transition-colors text-xs font-medium disabled:opacity-50"
        >
          {loading ? 'Loading…' : isReplayMode ? 'Reload' : 'Load Mission Data'}
        </button>
      </div>

      {missions.error && (
        <p className="mb-3 text-xs text-alert-red">Mission list unavailable — {missions.error}</p>
      )}

      {/* Transport */}
      <div className="flex items-center justify-center gap-3 mb-4">
        <button
          onClick={() => seekReplay(0)}
          disabled={!isReplayMode}
          className="p-2 rounded-lg bg-cockpit-surface hover:bg-cockpit-border transition-colors disabled:opacity-40"
          title="Reset to start"
        >
          <RotateCcw className="w-4 h-4 text-cockpit-muted" />
        </button>
        <button
          onClick={() => step(-0.05)}
          disabled={!isReplayMode}
          className="p-2 rounded-lg bg-cockpit-surface hover:bg-cockpit-border transition-colors disabled:opacity-40"
          title="Skip back 5%"
        >
          <SkipBack className="w-4 h-4 text-white" />
        </button>
        <button
          onClick={() => setReplayPlaying(!replayPlaying)}
          disabled={!isReplayMode || replayData.length === 0}
          className={clsx(
            'p-4 rounded-full transition-all disabled:opacity-40',
            replayPlaying
              ? 'bg-hud-amber text-cockpit-bg hover:bg-hud-amber/80'
              : 'bg-cyber-cyan text-cockpit-bg hover:bg-cyber-cyan/80'
          )}
          title={replayPlaying ? 'Pause' : 'Play'}
        >
          {replayPlaying ? <Pause className="w-5 h-5" /> : <Play className="w-5 h-5 ml-0.5" />}
        </button>
        <button
          onClick={() => step(0.05)}
          disabled={!isReplayMode}
          className="p-2 rounded-lg bg-cockpit-surface hover:bg-cockpit-border transition-colors disabled:opacity-40"
          title="Skip forward 5%"
        >
          <SkipForward className="w-4 h-4 text-white" />
        </button>

        <div className="flex items-center gap-1 ml-2">
          {PLAYBACK_SPEEDS.map((speed) => (
            <button
              key={speed}
              onClick={() => setReplaySpeed(speed)}
              className={clsx(
                'px-2 py-1 rounded text-xs font-medium transition-colors',
                replaySpeed === speed
                  ? 'bg-cyber-cyan text-cockpit-bg'
                  : 'bg-cockpit-surface text-cockpit-muted hover:bg-cockpit-border'
              )}
            >
              {speed}x
            </button>
          ))}
        </div>
      </div>

      {/* Timeline */}
      <div className="relative">
        <div className="flex justify-between mb-2 text-xs font-mono text-cockpit-muted">
          <span>{frame ? `${frame.timestamp.slice(11, 19)} UTC` : '--:--:--'}</span>
          <span>
            {replayData.length > 0
              ? `frame ${replayIndex + 1} / ${replayData.length}`
              : 'no mission loaded'}
          </span>
        </div>

        <div className="relative h-8">
          <div className="absolute inset-x-0 top-1/2 -translate-y-1/2 h-2 bg-cockpit-border rounded-full" />
          <div
            className="absolute inset-x-0 top-1/2 -translate-y-1/2 h-2 bg-cyber-cyan rounded-full"
            style={{ width: `${shown}%` }}
          />
          {markers.map((marker, i) => (
            <div
              key={`${marker.type}-${i}`}
              className={clsx(
                'absolute top-1/2 -translate-y-1/2 w-2 h-4 rounded-sm z-10',
                marker.severity === 'critical' ? 'bg-alert-red' : 'bg-hud-amber'
              )}
              style={{ left: `${marker.at}%` }}
              title={marker.label}
            />
          ))}
          <input
            type="range"
            min="0"
            max="100"
            step="0.1"
            value={shown}
            onChange={onScrub}
            disabled={replayData.length === 0}
            className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-20 disabled:cursor-not-allowed"
          />
          <div
            className="absolute top-1/2 -translate-y-1/2 -translate-x-1/2 w-4 h-4 rounded-full bg-white border-2 border-cyber-cyan shadow-lg pointer-events-none"
            style={{ left: `${shown}%` }}
          />
        </div>

        {/* Legend — always shown, so an empty timeline still explains itself. */}
        <div className="flex items-center justify-center gap-4 mt-3 text-xs text-cockpit-muted">
          <span className="flex items-center gap-1">
            <span className="w-2 h-3 bg-hud-amber rounded-sm" /> Anomaly
          </span>
          <span className="flex items-center gap-1">
            <span className="w-2 h-3 bg-alert-red rounded-sm" /> Critical
          </span>
          <span className="flex items-center gap-1">
            <span className="w-2 h-3 bg-cyber-cyan rounded-sm" /> RTB event
          </span>
        </div>
      </div>

      {/* Current frame */}
      {frame && (
        <div className="mt-4 pt-4 border-t border-cockpit-border grid grid-cols-4 gap-2 text-xs">
          <div className="text-center">
            <p className="text-cockpit-muted">RPM</p>
            <p className="data-display text-white">{frame.rpm?.toFixed(0) ?? '---'}</p>
          </div>
          <div className="text-center">
            <p className="text-cockpit-muted">EHI</p>
            <p className="data-display text-cyber-cyan">
              {frame.health?.ehi?.toFixed(1) ?? '---'}
            </p>
          </div>
          <div className="text-center">
            <p className="text-cockpit-muted">Anomaly</p>
            <p
              className={clsx(
                'data-display',
                (frame.anomaly?.score ?? 0) > 50 ? 'text-alert-red' : 'text-nominal-green'
              )}
            >
              {frame.anomaly?.score?.toFixed(0) ?? '0'}
            </p>
          </div>
          <div className="text-center">
            <p className="text-cockpit-muted">RUL</p>
            <p className="data-display text-hud-amber">
              {frame.prognostics?.predicted_rul_min
                ? `${frame.prognostics.predicted_rul_min.toFixed(0)}m`
                : '---'}
            </p>
          </div>
        </div>
      )}

      {backendReplay.data && !backendReplay.data.is_running && isReplayMode && (
        <p className="mt-3 text-[10px] text-cockpit-muted">
          Playing locally from stored frames — the backend replay streamer is idle.
        </p>
      )}

      {replayData.length > 0 && (
        <p className="mt-3 text-[10px] text-cockpit-muted">
          Loaded span {fmtClock((replayData[replayData.length - 1]?.frame_id ?? 0) / 10)} of
          engine time.
        </p>
      )}
    </div>
  );
}

/*  Markers are derived from the joined frames: an injected fault, a detected
    anomaly, or an RTB advisory/critical, each placed on the timeline once per
    transition so a long fault does not paint the whole bar.  */
function buildMarkers(frames: { injected_fault?: string | null; anomaly?: { score: number; is_detected: boolean }; prognostics?: { rtb_alert_level: string } }[]): TimelineMarker[] {
  const out: TimelineMarker[] = [];
  let lastFault: string | null = null;
  let lastRtb = 'NONE';
  let lastAnomaly = false;

  frames.forEach((f, i) => {
    const at = (i / Math.max(1, frames.length - 1)) * 100;

    if (f.injected_fault && f.injected_fault !== lastFault) {
      out.push({ at, type: 'fault', label: `Fault injected: ${f.injected_fault}`, severity: 'critical' });
    }
    lastFault = f.injected_fault ?? null;

    const rtb = f.prognostics?.rtb_alert_level ?? 'NONE';
    if (rtb !== 'NONE' && rtb !== lastRtb) {
      out.push({
        at,
        type: 'rtb',
        label: rtb === 'RTB_CRITICAL' ? 'RTB critical' : 'RTB advisory',
        severity: rtb === 'RTB_CRITICAL' ? 'critical' : 'warning',
      });
    }
    lastRtb = rtb;

    const anomaly = Boolean(f.anomaly?.is_detected) && (f.anomaly?.score ?? 0) > 60;
    if (anomaly && !lastAnomaly) {
      out.push({
        at,
        type: 'anomaly',
        label: `Anomaly detected (score ${f.anomaly?.score?.toFixed(0)})`,
        severity: (f.anomaly?.score ?? 0) > 80 ? 'critical' : 'warning',
      });
    }
    lastAnomaly = anomaly;
  });

  return out;
}
