// ══════════════════════════════════════════════════════════════════════════════
// Aero Piston Engine Digital Twin - Master Cockpit Layout
// ══════════════════════════════════════════════════════════════════════════════
//
// Complete cockpit interface assembling every backend capability:
// - Top navigation with live clock, frame counter, connection status
// - Cockpit overview, 3D twin, cutaway twin, mission control, diagnostics,
//   reports
// - Fault injection console (real backend fault catalogue) in a demo drawer
// - Incident log backed by the injected-fault audit trail
//
// Views are fed by the FastAPI backend: live frames over
// /ws/telemetry/{engine_id}, everything else through src/services/api.ts.
// ══════════════════════════════════════════════════════════════════════════════

import React, { useState, useEffect } from 'react';
import { TelemetryProvider, useTelemetry, type ConnectionStatus } from './context/TelemetryContext';
import { ToastProvider } from './components/ui/Toast';
import { useAudioAlarm } from './hooks/useAudioAlarm';

// Dashboard Components
import {
  MasterHealthGauge,
  ReturnToBaseHUD,
  TelemetryStripCharts,
  SensorHealthStatus,
  PhysicsResidualsPanel,
} from './components/dashboard';

// 3D Components
import { Engine3DView, CutawayTwinView } from './components/digital_twin';

// Diagnostics Components
import { MissionReplayToolbar, FaultConsolePanel, FaultHistoryTable } from './components/diagnostics';

// Mission & Report Components
import { MissionControlPanel, MissionBrowser } from './components/mission';
import { MissionReportPanel } from './components/reports';

// Icons
import {
  Activity,
  Wifi,
  WifiOff,
  Layers,
  Box,
  AlertTriangle,
  ChevronUp,
  ChevronDown,
  X,
  Settings2,
  FileText,
  Sparkles,
  ThermometerSun,
  Volume2,
  VolumeX,
  SlidersHorizontal,
} from 'lucide-react';

import clsx from 'clsx';

// ══════════════════════════════════════════════════════════════════════════════
// Types
// ══════════════════════════════════════════════════════════════════════════════

type ViewMode = 'overview' | '3d' | 'cutaway' | 'mission' | 'diagnostics' | 'reports';

// ══════════════════════════════════════════════════════════════════════════════
// Demo Control Panel
// ══════════════════════════════════════════════════════════════════════════════
//
// The judge-facing drawer: the fault catalogue comes from the backend itself
// (GET /api/faults/types), so every button injects a fault the engine can
// actually produce, and each press lands in the incident log.
// ══════════════════════════════════════════════════════════════════════════════

interface DemoControlPanelProps {
  isOpen: boolean;
  onToggle: () => void;
  missionId: string | null;
}

function DemoControlPanel({ isOpen, onToggle, missionId }: DemoControlPanelProps) {
  return (
    <div className={clsx(
      'fixed bottom-0 left-0 right-0 z-40 transition-transform duration-300',
      isOpen ? 'translate-y-0' : 'translate-y-[calc(100%-40px)]'
    )}>
      {/* Toggle Bar */}
      <button
        onClick={onToggle}
        className="w-full h-10 bg-cockpit-surface border-t border-cockpit-border flex items-center justify-center gap-2 hover:bg-cockpit-border transition-colors"
      >
        <ChevronUp className={clsx('w-4 h-4', isOpen && 'rotate-180')} />
        <span className="text-sm font-medium text-cockpit-muted">
          Demo Control Panel — fault injection
        </span>
        <ChevronDown className={clsx('w-4 h-4', isOpen && 'rotate-180')} />
      </button>

      {/* Panel Content */}
      <div className="bg-cockpit-bg border-t border-cockpit-border p-4 max-h-[70vh] overflow-auto">
        <div className="max-w-6xl mx-auto">
          <div className="flex items-center justify-between mb-4">
            <h3 className="text-sm font-medium text-hud-amber flex items-center gap-2">
              <Settings2 className="w-4 h-4" />
              Interactive Judge Demo Controls
            </h3>
            <p className="text-xs text-cockpit-muted">
              Faults ramp in over about a minute — watch EGT, CHT and vibration follow
            </p>
          </div>

          <FaultConsolePanel missionId={missionId} />
        </div>
      </div>
    </div>
  );
}

// ══════════════════════════════════════════════════════════════════════════════
// Incident Log Modal
// ══════════════════════════════════════════════════════════════════════════════
//
// Backed by GET /api/faults/history — the audit trail the backend writes for
// every injection (REST and WebSocket). The previous version fetched
// /api/logs/download, an endpoint that does not exist, so it always rendered
// "No incident logs found".
// ══════════════════════════════════════════════════════════════════════════════

interface IncidentLogModalProps {
  isOpen: boolean;
  onClose: () => void;
  missionId?: string | null;
}

function IncidentLogModal({ isOpen, onClose, missionId }: IncidentLogModalProps) {
  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/70 backdrop-blur-sm">
      <div className="glass-card w-[90vw] max-w-4xl max-h-[80vh] flex flex-col">
        {/* Header */}
        <div className="flex items-center justify-between p-4 border-b border-cockpit-border">
          <div className="flex items-center gap-3">
            <AlertTriangle className="w-5 h-5 text-hud-amber" />
            <h2 className="text-lg font-bold text-white">Incident Log</h2>
            <span className="text-xs text-cockpit-muted">
              {missionId ? `mission ${missionId.slice(0, 8)}` : 'all missions'}
            </span>
          </div>
          <button
            onClick={onClose}
            className="p-2 rounded-lg bg-cockpit-surface hover:bg-cockpit-border transition-colors"
          >
            <X className="w-4 h-4 text-cockpit-muted" />
          </button>
        </div>

        {/* Content */}
        <div className="flex-1 overflow-auto p-4">
          <FaultHistoryTable missionId={missionId} />
        </div>

        {/* Footer */}
        <div className="p-4 border-t border-cockpit-border flex items-center justify-end">
          <button
            onClick={onClose}
            className="px-4 py-2 rounded-lg bg-cockpit-surface hover:bg-cockpit-border transition-colors text-sm"
          >
            Close
          </button>
        </div>
      </div>
    </div>
  );
}

// ══════════════════════════════════════════════════════════════════════════════
// Top Navigation Bar
// ══════════════════════════════════════════════════════════════════════════════

interface TopNavBarProps {
  viewMode: ViewMode;
  onViewModeChange: (mode: ViewMode) => void;
  onOpenIncidents: () => void;
}

function TopNavBar({ viewMode, onViewModeChange, onOpenIncidents }: TopNavBarProps) {
  const { connectionStatus, frameHistory, isReplayMode, warmingUp } = useTelemetry();
  const { isMuted, toggleMute, initialize: initAudio } = useAudioAlarm();
  const [currentTime, setCurrentTime] = useState(new Date());

  // Update clock every second
  useEffect(() => {
    const timer = setInterval(() => setCurrentTime(new Date()), 1000);
    return () => clearInterval(timer);
  }, []);

  const connectionStatusColor: Record<ConnectionStatus, string> = {
    CONNECTED: 'bg-nominal-green',
    RECONNECTING: 'bg-hud-amber animate-pulse',
    DISCONNECTED: 'bg-alert-red animate-pulse',
  };

  const views: { id: ViewMode; label: string; icon: React.ReactNode }[] = [
    { id: 'overview', label: 'Cockpit', icon: <Layers className="w-4 h-4" /> },
    { id: '3d', label: '3D Twin', icon: <Box className="w-4 h-4" /> },
    { id: 'cutaway', label: 'Cutaway', icon: <Sparkles className="w-4 h-4" /> },
    { id: 'mission', label: 'Mission', icon: <SlidersHorizontal className="w-4 h-4" /> },
    { id: 'diagnostics', label: 'Diagnostics', icon: <AlertTriangle className="w-4 h-4" /> },
    { id: 'reports', label: 'Reports', icon: <FileText className="w-4 h-4" /> },
  ];

  return (
    <header className="h-14 bg-cockpit-surface border-b border-cockpit-border flex items-center justify-between px-4 z-50">
      {/* Left: Title */}
      <div className="flex items-center gap-3">
        <div className="w-8 h-8 rounded-lg bg-gradient-to-br from-cyber-cyan to-hud-amber flex items-center justify-center">
          <Activity className="w-5 h-5 text-cockpit-bg" />
        </div>
        <div className="hidden lg:block">
          <h1 className="text-sm font-bold text-white leading-tight">
            AeroTwin: MALE UAV Aero-Engine Digital Twin
          </h1>
          <p className="text-[10px] text-cockpit-muted">
            DRDO Tapas-BH-201 Simulation
          </p>
        </div>
      </div>

      {/* Center: View Tabs */}
      <nav className="flex items-center gap-1 bg-cockpit-bg rounded-lg p-1">
        {views.map((view) => (
          <button
            key={view.id}
            onClick={() => onViewModeChange(view.id)}
            className={clsx(
              'flex items-center gap-2 px-3 py-1.5 rounded-md text-sm font-medium transition-all',
              viewMode === view.id
                ? 'bg-cockpit-surface text-white shadow-lg'
                : 'text-cockpit-muted hover:text-white'
            )}
          >
            {view.icon}
            <span className="hidden xl:inline">{view.label}</span>
          </button>
        ))}
      </nav>

      {/* Right: Status Indicators */}
      <div className="flex items-center gap-3">
        {/* Warm-up */}
        {warmingUp && (
          <div
            className="flex items-center gap-1 px-2 py-1 rounded bg-hud-amber/20 border border-hud-amber/50"
            title="Engine below operating temperature — health index is indicative"
          >
            <ThermometerSun className="w-3.5 h-3.5 text-hud-amber" />
            <span className="text-xs text-hud-amber font-medium">WARM-UP</span>
          </div>
        )}

        {/* Audio Toggle */}
        <button
          onClick={() => {
            initAudio();
            toggleMute();
          }}
          className={clsx(
            'p-2 rounded-lg transition-colors',
            isMuted ? 'bg-cockpit-surface text-cockpit-muted' : 'bg-cyber-cyan/20 text-cyber-cyan'
          )}
          title={isMuted ? 'Unmute alarms' : 'Mute alarms'}
        >
          {isMuted ? <VolumeX className="w-4 h-4" /> : <Volume2 className="w-4 h-4" />}
        </button>

        {/* Incident Logs */}
        <button
          onClick={onOpenIncidents}
          className="p-2 rounded-lg bg-cockpit-surface hover:bg-cockpit-border transition-colors"
          title="View injected-fault log"
        >
          <AlertTriangle className="w-4 h-4 text-hud-amber" />
        </button>

        {/* Frame Counter */}
        <div className="text-right hidden md:block">
          <p className="text-xs text-cockpit-muted">Frames</p>
          <p className="data-display text-sm text-white">{frameHistory.length}</p>
        </div>

        {/* UTC Clock */}
        <div className="text-right hidden md:block">
          <p className="text-xs text-cockpit-muted">UTC</p>
          <p className="data-display text-sm text-cyber-cyan">
            {currentTime.toUTCString().slice(17, 25)}
          </p>
        </div>

        {/* Connection Status */}
        <div className="flex items-center gap-2">
          <div className={clsx('w-3 h-3 rounded-full', connectionStatusColor[connectionStatus])} />
          {connectionStatus === 'CONNECTED' ? (
            <Wifi className="w-4 h-4 text-nominal-green" />
          ) : (
            <WifiOff className="w-4 h-4 text-alert-red" />
          )}
        </div>

        {/* Replay Mode Indicator */}
        {isReplayMode && (
          <div className="px-2 py-1 rounded bg-hud-amber/20 border border-hud-amber">
            <span className="text-xs text-hud-amber font-medium">REPLAY</span>
          </div>
        )}
      </div>
    </header>
  );
}

// ══════════════════════════════════════════════════════════════════════════════
// View: Cockpit Overview
// ══════════════════════════════════════════════════════════════════════════════

function CockpitOverview() {
  return (
    <div className="grid grid-cols-12 gap-4 h-full">
      {/* Left Column: Health & RTB */}
      <div className="col-span-12 lg:col-span-3 space-y-4">
        <MasterHealthGauge size={280} />
        <ReturnToBaseHUD />
      </div>

      {/* Center Column: 3D View */}
      <div className="col-span-12 lg:col-span-5">
        <div className="hud-panel h-[500px]">
          <Engine3DView showControls={true} />
        </div>
      </div>

      {/* Right Column: Sensors */}
      <div className="col-span-12 lg:col-span-4">
        <SensorHealthStatus />
      </div>

      {/* Bottom: Strip Charts */}
      <div className="col-span-12">
        <TelemetryStripCharts />
      </div>

      {/* Explainability: what the physics model expected */}
      <div className="col-span-12">
        <PhysicsResidualsPanel />
      </div>
    </div>
  );
}

// ══════════════════════════════════════════════════════════════════════════════
// View: 3D Digital Twin Detailed
// ══════════════════════════════════════════════════════════════════════════════

function DigitalTwinDetailed() {
  return (
    <div className="grid grid-cols-12 gap-4 h-full">
      {/* Main 3D View */}
      <div className="col-span-12 lg:col-span-8">
        <div className="hud-panel h-[600px]">
          <Engine3DView showControls={true} />
        </div>
      </div>

      {/* Right Panel */}
      <div className="col-span-12 lg:col-span-4 space-y-4">
        <MasterHealthGauge size={250} />
        <SensorHealthStatus compact />
      </div>

      {/* Bottom: Charts */}
      <div className="col-span-12">
        <TelemetryStripCharts />
      </div>
    </div>
  );
}

// ══════════════════════════════════════════════════════════════════════════════
// View: Cutaway Engine Twin
// ══════════════════════════════════════════════════════════════════════════════
//
// The detailed cutaway viewer — STL engine block and piston, section plane,
// staged system strip-down, per-part tooltips — driven by the live twin state,
// with the same health, RTB and sensor panels the other views use.
// ══════════════════════════════════════════════════════════════════════════════

function CutawayTwinDetailed() {
  return (
    <div className="grid grid-cols-12 gap-4 h-full">
      {/* Main cutaway view */}
      <div className="col-span-12 xl:col-span-9">
        <div className="hud-panel h-[640px]">
          <CutawayTwinView showControls={true} />
        </div>
      </div>

      {/* Live health */}
      <div className="col-span-12 xl:col-span-3 space-y-4">
        <MasterHealthGauge size={250} />
        <ReturnToBaseHUD />
        <SensorHealthStatus compact />
      </div>

      {/* Trends */}
      <div className="col-span-12">
        <TelemetryStripCharts />
      </div>

      {/* Physics evidence */}
      <div className="col-span-12">
        <PhysicsResidualsPanel />
      </div>
    </div>
  );
}

// ══════════════════════════════════════════════════════════════════════════════
// View: Mission Control
// ══════════════════════════════════════════════════════════════════════════════

interface MissionControlViewProps {
  onMissionChanged: (missionId: string | null) => void;
  currentMissionId: string | null;
  onReplay: (missionId: string) => void;
  onOpenReport: (missionId: string) => void;
}

function MissionControlView({
  onMissionChanged,
  currentMissionId,
  onReplay,
  onOpenReport,
}: MissionControlViewProps) {
  return (
    <div className="grid grid-cols-12 gap-4 h-full">
      <div className="col-span-12 lg:col-span-4 space-y-4">
        <MissionControlPanel onMissionChanged={onMissionChanged} />
      </div>

      <div className="col-span-12 lg:col-span-4">
        <MissionBrowser
          currentMissionId={currentMissionId}
          onReplay={onReplay}
          onOpenReport={onOpenReport}
        />
      </div>

      <div className="col-span-12 lg:col-span-4">
        <FaultConsolePanel missionId={currentMissionId} />
      </div>

      <div className="col-span-12">
        <PhysicsResidualsPanel />
      </div>
    </div>
  );
}

// ══════════════════════════════════════════════════════════════════════════════
// View: Diagnostics & Logs
// ══════════════════════════════════════════════════════════════════════════════

interface DiagnosticsViewProps {
  replayMissionId: string | null;
  currentMissionId: string | null;
}

function DiagnosticsView({ replayMissionId, currentMissionId }: DiagnosticsViewProps) {
  return (
    <div className="grid grid-cols-12 gap-4 h-full">
      {/* Left: Replay Toolbar */}
      <div className="col-span-12 lg:col-span-5 space-y-4">
        <MissionReplayToolbar missionId={replayMissionId} />
        <ReturnToBaseHUD />
      </div>

      {/* Center: 3D View */}
      <div className="col-span-12 lg:col-span-4">
        <div className="hud-panel h-[400px]">
          <Engine3DView showControls={false} />
        </div>
        <div className="mt-4">
          <SensorHealthStatus compact />
        </div>
      </div>

      {/* Right: Health + faults */}
      <div className="col-span-12 lg:col-span-3 space-y-4">
        <MasterHealthGauge size={220} />
        <FaultConsolePanel missionId={currentMissionId} />
      </div>

      {/* Bottom: Charts + physics */}
      <div className="col-span-12">
        <TelemetryStripCharts />
      </div>
      <div className="col-span-12">
        <PhysicsResidualsPanel />
      </div>
    </div>
  );
}

// ══════════════════════════════════════════════════════════════════════════════
// View: Reports
// ══════════════════════════════════════════════════════════════════════════════

interface ReportsViewProps {
  reportMissionId: string | null;
  currentMissionId: string | null;
  onReportMissionChange: (missionId: string) => void;
  onReplay: (missionId: string) => void;
}

function ReportsView({
  reportMissionId,
  currentMissionId,
  onReportMissionChange,
  onReplay,
}: ReportsViewProps) {
  return (
    <div className="grid grid-cols-12 gap-4 h-full">
      <div className="col-span-12 xl:col-span-8">
        <MissionReportPanel missionId={reportMissionId} onMissionChange={onReportMissionChange} />
      </div>

      <div className="col-span-12 xl:col-span-4 space-y-4">
        <MissionBrowser
          currentMissionId={currentMissionId ?? reportMissionId}
          onReplay={onReplay}
          onOpenReport={onReportMissionChange}
        />
        <MasterHealthGauge size={220} />
      </div>
    </div>
  );
}

// ══════════════════════════════════════════════════════════════════════════════
// Main Dashboard Component
// ══════════════════════════════════════════════════════════════════════════════

function Dashboard() {
  const [viewMode, setViewMode] = useState<ViewMode>('overview');
  const [isDemoPanelOpen, setIsDemoPanelOpen] = useState(false);
  const [isIncidentModalOpen, setIsIncidentModalOpen] = useState(false);

  /** The mission the backend is running (from Mission Control / simulation). */
  const [currentMissionId, setCurrentMissionId] = useState<string | null>(null);
  /** Mission picked for playback, and the one picked for a report. */
  const [replayMissionId, setReplayMissionId] = useState<string | null>(null);
  const [reportMissionId, setReportMissionId] = useState<string | null>(null);

  const openReplay = (missionId: string) => {
    setReplayMissionId(missionId);
    setViewMode('diagnostics');
  };

  const openReport = (missionId: string) => {
    setReportMissionId(missionId);
    setViewMode('reports');
  };

  const renderView = () => {
    switch (viewMode) {
      case 'overview':
        return <CockpitOverview />;
      case '3d':
        return <DigitalTwinDetailed />;
      case 'cutaway':
        return <CutawayTwinDetailed />;
      case 'mission':
        return (
          <MissionControlView
            onMissionChanged={setCurrentMissionId}
            currentMissionId={currentMissionId}
            onReplay={openReplay}
            onOpenReport={openReport}
          />
        );
      case 'diagnostics':
        return (
          <DiagnosticsView
            replayMissionId={replayMissionId}
            currentMissionId={currentMissionId}
          />
        );
      case 'reports':
        return (
          <ReportsView
            reportMissionId={reportMissionId}
            currentMissionId={currentMissionId}
            onReportMissionChange={setReportMissionId}
            onReplay={openReplay}
          />
        );
      default:
        return <CockpitOverview />;
    }
  };

  return (
    <div className="min-h-screen bg-cockpit-bg flex flex-col">
      {/* Top Navigation */}
      <TopNavBar
        viewMode={viewMode}
        onViewModeChange={setViewMode}
        onOpenIncidents={() => setIsIncidentModalOpen(true)}
      />

      {/* Main Content */}
      <main className="flex-1 overflow-auto p-4 pb-24">
        {renderView()}
      </main>

      {/* Demo Control Panel */}
      <DemoControlPanel
        isOpen={isDemoPanelOpen}
        onToggle={() => setIsDemoPanelOpen(!isDemoPanelOpen)}
        missionId={currentMissionId}
      />

      {/* Incident Log Modal */}
      <IncidentLogModal
        isOpen={isIncidentModalOpen}
        onClose={() => setIsIncidentModalOpen(false)}
        missionId={currentMissionId}
      />
    </div>
  );
}

// ══════════════════════════════════════════════════════════════════════════════
// App Export with Providers
// ══════════════════════════════════════════════════════════════════════════════

function App() {
  return (
    <TelemetryProvider>
      <ToastProvider>
        <Dashboard />
      </ToastProvider>
    </TelemetryProvider>
  );
}

export default App;
